func (o *NotificationChannel) Preload(name string, retrieved any) error {
	if o == nil {
		return nil
	}

	switch name {
	case "AlertRules":
		rels, ok := retrieved.(AlertRuleSlice)
		if !ok {
			return fmt.Errorf("notificationChannel cannot load %T as %q", retrieved, name)
		}

		o.R.AlertRules = rels
		o.R.Loaded.AlertRules = true

		for _, rel := range rels {
			if rel != nil {
				rel.R.NotificationChannel = o
				rel.R.Loaded.NotificationChannel = true
			}
		}
		return nil
	case "User":
		rel, ok := retrieved.(*User)
		if !ok {
			return fmt.Errorf("notificationChannel cannot load %T as %q", retrieved, name)
		}

		o.R.User = rel
		o.R.Loaded.User = true

		if rel != nil {
			rel.R.NotificationChannels = NotificationChannelSlice{o}
		}
		return nil
	default:
		return fmt.Errorf("notificationChannel has no relationship %q", name)
	}
}

