// LoadAlertRules loads the notificationChannel's AlertRules into the .R struct
func (o *NotificationChannel) LoadAlertRules(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if o == nil {
		return nil
	}

	// Reset the relationship
	o.R.AlertRules = nil
	o.R.Loaded.AlertRules = false

	related, err := o.AlertRules(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, rel := range related {
		rel.R.NotificationChannel = o
		rel.R.Loaded.NotificationChannel = true
	}

	o.R.AlertRules = related
	o.R.Loaded.AlertRules = true
	return nil
}

// LoadAlertRules loads the notificationChannel's AlertRules into the .R struct
func (os NotificationChannelSlice) LoadAlertRules(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	alertRules, err := os.AlertRules(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.AlertRules = nil
		o.R.Loaded.AlertRules = true
	}
	// O(N+M) stitch via a map keyed by the join column (key -> []parent; was O(N*M)).
	notificationChannelByKey := make(map[string][]*NotificationChannel, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}

		notificationChannelByKey[o.ID] = append(notificationChannelByKey[o.ID], o)
	}

	for _, rel := range alertRules {

		owners, ok := notificationChannelByKey[rel.NotificationChannelID]
		if !ok {
			continue
		}

		for _, o := range owners {

			rel.R.NotificationChannel = o
			rel.R.Loaded.NotificationChannel = true

			o.R.AlertRules = append(o.R.AlertRules, rel)

		}
	}

	return nil
}

// LoadUser loads the notificationChannel's User into the .R struct
func (o *NotificationChannel) LoadUser(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if o == nil {
		return nil
	}

	// Reset the relationship
	o.R.User = nil
	o.R.Loaded.User = false

	related, err := o.User(mods...).One(ctx, exec)
	if err != nil {
		return err
	}

	related.R.NotificationChannels = NotificationChannelSlice{o}

	o.R.User = related
	o.R.Loaded.User = true
	return nil
}

// LoadUser loads the notificationChannel's User into the .R struct
func (os NotificationChannelSlice) LoadUser(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	users, err := os.User(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.User = nil
		o.R.Loaded.User = true
	}
	// O(N+M) stitch via a map keyed by the join column (key -> []parent; was O(N*M)).
	notificationChannelByKey := make(map[string][]*NotificationChannel, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}

		notificationChannelByKey[o.UserID] = append(notificationChannelByKey[o.UserID], o)
	}

	for _, rel := range users {

		owners, ok := notificationChannelByKey[rel.ID]
		if !ok {
			continue
		}

		for _, o := range owners {

			// to-one: keep only the first matching child (matches the previous break)
			if o.R.User != nil {
				continue
			}

			rel.R.NotificationChannels = append(rel.R.NotificationChannels, o)

			o.R.User = rel

		}
	}

	return nil
}

