type notificationChannelCountPreloader struct {
	AlertRules func(...bob.Mod[*dialect.SelectQuery]) sqlite.Preloader
}

func buildNotificationChannelCountPreloader() notificationChannelCountPreloader {
	return notificationChannelCountPreloader{
		AlertRules: func(mods ...bob.Mod[*dialect.SelectQuery]) sqlite.Preloader {
			return countPreloader[*NotificationChannel]("AlertRules", func(parent string) bob.Expression {
				// Build a correlated subquery: (SELECT COUNT(*) FROM related WHERE fk = parent.pk)
				if parent == "" {
					parent = NotificationChannels.Alias()
				}

				subqueryMods := []bob.Mod[*dialect.SelectQuery]{
					sm.Columns(sqlite.Raw("count(*)")),

					sm.From(AlertRules.NameAsExpr()),
					sm.Where(sqlite.Quote(AlertRules.Alias(), "notification_channel_id").EQ(sqlite.Quote(parent, "id"))),
				}
				subqueryMods = append(subqueryMods, mods...)
				return sqlite.Group(sqlite.Select(subqueryMods...).Expression)
			})
		},
	}
}

