// LoadCountAlertRules loads the count of AlertRules for a slice in a single batch query
func (os NotificationChannelSlice) LoadCountAlertRules(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	// Build the IN arg expression from parent PKs
	PKArgSlice := make([]bob.Expression, 0, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}
		PKArgSlice = append(PKArgSlice, sqlite.Arg(o.ID))
	}
	PKArgExpr := sqlite.Group(PKArgSlice...)

	// countResult holds one scanned row from the batch count query.
	// FK columns are aliased to the parent PK column names for direct map lookup.
	type countResult struct {
		ID    string
		Count int64
	}

	batchMods := []bob.Mod[*dialect.SelectQuery]{
		// SELECT fk AS parent_pk, count(*)
		sm.Columns(
			AlertRules.Columns.NotificationChannelID.As("id"),
			sqlite.Raw("count(*) as count"),
		),
		// Single-hop: FROM related table directly
		sm.From(AlertRules.NameAsExpr()),

		// WHERE fk IN (parent PKs) — psql single-column FK uses `= ANY(array)` (see PKArgExpr above)
		sm.Where(AlertRules.Columns.NotificationChannelID.OP("IN", PKArgExpr)),
		// GROUP BY fk columns
		sm.GroupBy(AlertRules.Columns.NotificationChannelID),
	}
	batchMods = append(batchMods, mods...)

	results, err := bob.All(ctx, exec,
		sqlite.Select(batchMods...),
		scan.StructMapper[countResult](),
	)
	if err != nil {
		return err
	}

	// Single-column FK: direct map lookup
	countMap := make(map[string]int64, len(results))
	for _, r := range results {
		countMap[r.ID] = r.Count
	}
	for _, o := range os {
		if o == nil {
			continue
		}
		count := countMap[o.ID]
		o.C.AlertRules = &count
	}

	return nil
}

type notificationChannelJoins[Q dialect.Joinable] struct {
	typ        string
	AlertRules modAs[Q, alertRuleColumns]
	User       modAs[Q, userColumns]
}

func (j notificationChannelJoins[Q]) aliasedAs(alias string) notificationChannelJoins[Q] {
	return buildNotificationChannelJoins[Q](buildNotificationChannelColumns(alias), j.typ)
}

func buildNotificationChannelJoins[Q dialect.Joinable](cols notificationChannelColumns, typ string) notificationChannelJoins[Q] {
	return notificationChannelJoins[Q]{
		typ: typ,
		AlertRules: modAs[Q, alertRuleColumns]{
			c: AlertRules.Columns,
			f: func(to alertRuleColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, AlertRules.NameExpr().As(to.Alias())).On(
						to.NotificationChannelID.EQ(cols.ID),
					))
				}

				return mods
			},
		},
		User: modAs[Q, userColumns]{
			c: Users.Columns,
			f: func(to userColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Users.NameExpr().As(to.Alias())).On(
						to.ID.EQ(cols.UserID),
					))
				}

				return mods
			},
		},
	}
}
